export const GINGER=Object.freeze({name:'Just Ginger',special:'Clip That!',kind:'gingerCamera',duration:1.72,range:900,color:'#ff9e50',glow:'rgba(255,145,60,.4)'});
const LAUNCH=.55, SPEED=1100;
export function createGingerSpecial(a,b){const gap=(b.x-a.x)*a.facing;const cameraOffset=Math.max(12,Math.min(105,gap*.48));return {kind:GINGER.kind,owner:a.id,facing:a.facing,originX:a.x,x:a.x,age:0,ttl:GINGER.duration,duration:GINGER.duration,active:true,delay:0,hitCount:0,fired:false,cameraOffset};}
export function endGingerSpecial(g,a,s){s.active=false;s.ttl=0;if(a){a.vx=0;a.actionRemaining=0;g.setState(a,a.hp>0?'idle':'ko');}}
export function updateGingerSpecial(g,s,a,b){if(!a||!b){endGingerSpecial(g,a,s);return;}a.facing=s.facing;a.vx=0;if(s.ttl>1e-9){a.state='special';a.actionRemaining=Math.max(a.actionRemaining,s.ttl);}const start=s.cameraOffset+25;const d=Math.min(GINGER.range,start+Math.max(0,s.age-LAUNCH)*SPEED);s.x=s.originX+d*s.facing;if(s.age>=LAUNCH&&!s.fired){const dx=(b.x-s.originX)*s.facing;if(dx>=0&&dx<=GINGER.range&&dx<=d+32&&b.y<185){s.fired=true;if(g.hit(a,b,46,s.kind,330,.32,s.x))s.hitCount=1;}else if(d>=GINGER.range)s.fired=true;}if(s.ttl<=1e-9)endGingerSpecial(g,a,s);}
export function gingerPose(f,s){const t=Math.max(0,f.stateTime||0),p=Math.min(1,Math.max(0,f.attackProgress||0));let index=0;if(f.state==='special'){const age=s?.age??t;index=age<.28?10:age<LAUNCH+.14?19:age<1.35?1:0;}else if(f.state==='punch')index=p<.23?10:p<.52?11:p<.82?12:1;else if(f.state==='kick')index=p<.22?1:p<.79?13:0;else if(f.state==='block')index=14;else if(f.state==='ko')index=16;else if(f.state==='hurt'||f.state==='grabbed'||f.state==='beltHeld')index=15;else if(!f.grounded||f.state==='jump'||f.state==='fall')index=t<.08?6:(f.vy??0)>0?7:8;else if(f.gingerLandRemaining>0&&f.state==='idle')index=9;else if(f.state==='recover')index=17;else if(f.state==='run')index=[4,5][Math.floor(t*10)%2];else if(f.state==='walk')index=[2,3][Math.floor(t*6)%2];else index=Math.floor(t*2)%2;return {key:'justginger',index};}
export function drawGingerCamera(ctx,s,g,ground,draw){const a=g.fighters.find(f=>f.id===s.owner);if(!a||s.age<.06||s.age>1.62)return;const age=s.age,fade=Math.max(0,Math.min(1,(age-.06)*15,(1.62-age)*8));const offset=s.cameraOffset??95;ctx.save();ctx.globalAlpha=fade;const facing=s.facing;draw(age<LAUNCH?20:23,s.originX+offset*facing,ground,facing,1);if(age>=LAUNCH&&!s.fired){const d=Math.min(GINGER.range,offset+25+(age-LAUNCH)*SPEED);draw(22,s.originX+d*facing,ground-105,facing,.58);}if(age>=LAUNCH&&age<1.12){const x=a.x,y=ground-258;ctx.fillStyle='#fff';ctx.strokeStyle='#17141c';ctx.lineWidth=3;ctx.beginPath();ctx.roundRect(x-65,y-20,130,41,10);ctx.fill();ctx.stroke();ctx.fillStyle='#17141c';ctx.font='bold 22px sans-serif';ctx.textAlign='center';ctx.fillText('clip that!',x,y+7);}ctx.restore();}
